	 state     <= state_empty;
	 addr      <= 0;
         addr_full <= 0;
	 o_v_reg   <= 0;

	 i_b_reg   <= 0;
	 maxcount_reg <= 0;

      end
      else begin
	 state     <= state_;
	 addr      <= addr_;
         addr_full <= addr_full_;
	 o_v_reg   <= o_v_reg_;
	 i_b_reg   <= i_b_reg_;
	 maxcount_reg <= (count > maxcount_reg ? count : maxcount_reg);
      end
   end // always @ (posedge clock)

