    $readmemh("/home/miguel_tfg/FINN-v0.9-Stable/notebooks/UAH_example/FINN_build/code_gen_ipgen_MatrixVectorActivation_0_gxtl723z/project_MatrixVectorActivation_0/sol1/impl/ip/hdl/verilog/MatrixVectorActivation_0_Matrix_Vector_Activate_Stream_Batch_p_ZL7threshs_0_1_ROM_AUTO_1R.dat", rom0);
